"use client";

import Link from "next/link";
import { FormEvent, useEffect, useMemo, useState } from "react";
import { useParams } from "next/navigation";
import {
  ApiError,
  fetchAssessment,
  putScores,
  type AssessmentViewOut,
  type ScorePutOut,
} from "@/lib/api";
import {
  ApiErrorAlert,
  FieldMessage,
  fieldErrorMap,
} from "@/components/forms/ApiErrorAlert";
import { PageHeader } from "@/components/layout/PageHeader";
import { PageShell } from "@/components/layout/PageShell";
import { StatusBadge } from "@/components/layout/StatusBadge";
import { Alert, AlertDescription, AlertTitle } from "@/components/ui/alert";
import { Button } from "@/components/ui/button";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";

type MarkDraft = {
  value: string;
  comment: string;
};

function criterionIdOf(c: { criterionId?: string; id?: string }): string {
  return String(c.criterionId ?? c.id ?? "");
}

function criterionMax(c: { max?: number; maxMark?: number }): number | null {
  if (typeof c.max === "number") return c.max;
  if (typeof c.maxMark === "number") return c.maxMark;
  return null;
}

export default function ExpertScorePage() {
  const params = useParams<{ submissionId: string }>();
  const submissionId = params.submissionId;

  const [view, setView] = useState<AssessmentViewOut | null>(null);
  const [marks, setMarks] = useState<Record<string, MarkDraft>>({});
  const [selectedPenalties, setSelectedPenalties] = useState<string[]>([]);
  const [scoreOut, setScoreOut] = useState<ScorePutOut | null>(null);
  const [error, setError] = useState<ApiError | null>(null);
  const [fieldErrors, setFieldErrors] = useState<Record<string, string>>({});
  const [loading, setLoading] = useState(true);
  const [pending, setPending] = useState(false);
  const [statusMessage, setStatusMessage] = useState<string | null>(null);

  useEffect(() => {
    let cancelled = false;
    async function load() {
      setLoading(true);
      setError(null);
      try {
        const out = await fetchAssessment(submissionId);
        if (cancelled) return;
        setView(out);
        const initial: Record<string, MarkDraft> = {};
        for (const c of out.criteria) {
          const id = criterionIdOf(c);
          if (!id) continue;
          const existing = out.myMarks.find((m) => m.criterionId === id);
          initial[id] = {
            value: existing?.value != null ? String(existing.value) : "",
            comment: existing?.comment ?? "",
          };
        }
        setMarks(initial);
        setSelectedPenalties([]);
      } catch (err) {
        if (!cancelled) {
          setError(
            err instanceof ApiError
              ? err
              : new ApiError(0, {
                  error: {
                    code: "HTTP_ERROR",
                    message: "Could not load assessment",
                    fields: [],
                    traceId: "",
                  },
                }),
          );
        }
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    void load();
    return () => {
      cancelled = true;
    };
  }, [submissionId]);

  const displayTotal = scoreOut?.total ?? view?.total ?? null;

  const penaltyOptions = useMemo(() => {
    if (!view) return [];
    return (view.penalties || []).map((p) => ({
      code: String(p.code ?? ""),
      deduction: p.deduction,
    })).filter((p) => p.code);
  }, [view]);

  async function save(finalize: boolean) {
    if (!view) return;
    setError(null);
    setFieldErrors({});
    setPending(true);
    setStatusMessage(null);
    try {
      const criterionMarks = view.criteria
        .map((c) => {
          const id = criterionIdOf(c);
          const draft = marks[id];
          if (!draft || draft.value.trim() === "") return null;
          const value = Number(draft.value);
          if (Number.isNaN(value)) return null;
          return {
            criterionId: id,
            type: String(c.type ?? "MEASUREMENT").toUpperCase(),
            value,
            comment: draft.comment.trim() || null,
          };
        })
        .filter(Boolean) as {
        criterionId: string;
        type: string;
        value: number;
        comment: string | null;
      }[];

      const out = await putScores(submissionId, {
        criterionMarks,
        penalties: selectedPenalties.map((code) => ({ code })),
        finalize,
      });
      setScoreOut(out);
      setStatusMessage(
        finalize
          ? `Scores finalised — total ${out.total}.`
          : `Draft saved — total ${out.total}.`,
      );
    } catch (err) {
      if (err instanceof ApiError) {
        setError(err);
        setFieldErrors(fieldErrorMap(err.fields));
      } else {
        setError(
          new ApiError(0, {
            error: {
              code: "HTTP_ERROR",
              message: "Could not save scores",
              fields: [],
              traceId: "",
            },
          }),
        );
      }
    } finally {
      setPending(false);
    }
  }

  function onSubmitDraft(e: FormEvent) {
    e.preventDefault();
    void save(false);
  }

  const blocked =
    error?.code === "CONFLICT_OF_INTEREST" ||
    error?.code === "NOT_ASSIGNED";

  return (
    <PageShell width="narrow" className="space-y-6">
      <PageHeader
        title="Score submission"
        description="Enter measurement and judgement marks from the rubric. Identity is hidden when blind mode is enabled."
      />

      {statusMessage ? (
        <Alert data-testid="assessment-status-message">
          <AlertTitle>Status</AlertTitle>
          <AlertDescription>{statusMessage}</AlertDescription>
        </Alert>
      ) : null}

      <ApiErrorAlert error={error} />

      {loading ? (
        <p className="text-sm text-muted-foreground" role="status">
          Loading assessment…
        </p>
      ) : null}

      {view ? (
        <Card data-testid="assessment-panel">
          <CardHeader>
            <CardTitle className="flex flex-wrap items-center gap-2 text-lg">
              <span data-testid="assessment-anon-code">{view.anonCode}</span>
              <StatusBadge status={view.state} />
              {view.blindMode ? (
                <StatusBadge status="blind" label="Blind mode" />
              ) : null}
            </CardTitle>
            <CardDescription>
              Submission{" "}
              <span className="font-mono text-xs">{view.submissionId}</span>
            </CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            {view.blindMode ? (
              <Alert data-testid="assessment-blind">
                <AlertTitle>Blind assessment</AlertTitle>
                <AlertDescription>
                  Competitor name, photo and institution are hidden. Score only
                  against the anonymised code and rubric.
                </AlertDescription>
              </Alert>
            ) : (
              <dl
                className="grid gap-2 text-sm sm:grid-cols-2"
                data-testid="assessment-identity"
              >
                <div>
                  <dt className="text-muted-foreground">Name</dt>
                  <dd>
                    {[view.givenNames, view.familyName]
                      .filter(Boolean)
                      .join(" ") || "—"}
                  </dd>
                </div>
                <div>
                  <dt className="text-muted-foreground">Institution</dt>
                  <dd className="font-mono text-xs">
                    {view.institutionId ?? "—"}
                  </dd>
                </div>
              </dl>
            )}

            {displayTotal != null ? (
              <p className="text-sm" data-testid="assessment-total">
                Total: <strong>{displayTotal}</strong>
              </p>
            ) : null}
          </CardContent>
        </Card>
      ) : null}

      {view && !blocked ? (
        <form onSubmit={onSubmitDraft} className="space-y-6" noValidate>
          <Card>
            <CardHeader>
              <CardTitle className="text-lg">Criteria</CardTitle>
              <CardDescription>
                Marks must stay within each criterion maximum. Finalise only when
                every criterion is marked.
              </CardDescription>
            </CardHeader>
            <CardContent className="space-y-6">
              {view.criteria.map((c) => {
                const id = criterionIdOf(c);
                const max = criterionMax(c);
                const type = String(c.type ?? "").toUpperCase();
                const name = String(c.name ?? c.label ?? id);
                const draft = marks[id] ?? { value: "", comment: "" };
                return (
                  <fieldset
                    key={id}
                    className="space-y-3 rounded-md border border-border p-4"
                    data-testid="assessment-criterion"
                    data-criterion={id}
                  >
                    <legend className="px-1 text-sm font-medium">
                      {name}{" "}
                      <span className="text-muted-foreground">
                        ({type}
                        {max != null ? ` · max ${max}` : ""})
                      </span>
                    </legend>
                    <div className="space-y-2">
                      <Label htmlFor={`mark-${id}`}>Mark</Label>
                      <Input
                        id={`mark-${id}`}
                        type="number"
                        inputMode="numeric"
                        className="min-h-11"
                        value={draft.value}
                        onChange={(e) =>
                          setMarks((prev) => ({
                            ...prev,
                            [id]: { ...draft, value: e.target.value },
                          }))
                        }
                        min={0}
                        max={max ?? undefined}
                        disabled={pending}
                        data-testid="assessment-mark"
                        aria-invalid={Boolean(fieldErrors[id])}
                        aria-describedby={
                          fieldErrors[id] ? `${id}-error` : undefined
                        }
                      />
                      <FieldMessage
                        id={`${id}-error`}
                        message={fieldErrors[id]}
                      />
                    </div>
                    <div className="space-y-2">
                      <Label htmlFor={`comment-${id}`}>Comment (optional)</Label>
                      <Textarea
                        id={`comment-${id}`}
                        value={draft.comment}
                        onChange={(e) =>
                          setMarks((prev) => ({
                            ...prev,
                            [id]: { ...draft, comment: e.target.value },
                          }))
                        }
                        disabled={pending}
                        rows={2}
                        data-testid="assessment-comment"
                      />
                    </div>
                  </fieldset>
                );
              })}
            </CardContent>
          </Card>

          {penaltyOptions.length > 0 ? (
            <Card>
              <CardHeader>
                <CardTitle className="text-lg">Penalties</CardTitle>
                <CardDescription>
                  Select configured penalties to apply. Caps are enforced by the
                  server.
                </CardDescription>
              </CardHeader>
              <CardContent className="space-y-3">
                {penaltyOptions.map((p) => {
                  const checked = selectedPenalties.includes(p.code);
                  return (
                    <label
                      key={p.code}
                      className="flex min-h-11 items-center gap-3 text-sm"
                    >
                      <Checkbox
                        checked={checked}
                        onCheckedChange={(v) => {
                          setSelectedPenalties((prev) =>
                            v
                              ? [...prev, p.code]
                              : prev.filter((c) => c !== p.code),
                          );
                        }}
                        disabled={pending}
                        data-testid="assessment-penalty"
                      />
                      <span>
                        {p.code}
                        {p.deduction != null ? ` (−${p.deduction})` : ""}
                      </span>
                    </label>
                  );
                })}
              </CardContent>
            </Card>
          ) : null}

          {scoreOut?.breakdown ? (
            <Card data-testid="assessment-breakdown">
              <CardHeader>
                <CardTitle className="text-lg">Breakdown</CardTitle>
              </CardHeader>
              <CardContent className="space-y-2 text-sm">
                <ul className="space-y-1">
                  {scoreOut.breakdown.marks.map((m) => (
                    <li key={`${m.criterionId}-${m.assessorId}`}>
                      {m.criterionId}: {m.value ?? "—"} ({m.status})
                    </li>
                  ))}
                </ul>
                {scoreOut.breakdown.penalties.length > 0 ? (
                  <ul className="space-y-1" data-testid="assessment-penalty-list">
                    {scoreOut.breakdown.penalties.map((p) => (
                      <li key={p.code}>
                        Penalty {p.code}: −{p.deduction}
                      </li>
                    ))}
                  </ul>
                ) : null}
                <p>
                  Breakdown total: <strong>{scoreOut.breakdown.total}</strong>
                </p>
              </CardContent>
            </Card>
          ) : null}

          <div className="flex flex-col gap-3 sm:flex-row">
            <Button
              type="submit"
              variant="outline"
              className="min-h-11 flex-1"
              disabled={pending}
              data-testid="assessment-save-draft"
            >
              {pending ? "Saving…" : "Save draft"}
            </Button>
            <Button
              type="button"
              className="min-h-11 flex-1"
              disabled={pending}
              onClick={() => void save(true)}
              data-testid="assessment-finalise"
            >
              {pending ? "Working…" : "Finalise scores"}
            </Button>
          </div>
        </form>
      ) : null}

      <p className="text-xs text-muted-foreground">
        <Link
          href="/expert"
          className="underline underline-offset-2"
          data-testid="assessment-back"
        >
          Back to assessor portal
        </Link>
        {" · "}
        <Link
          href={`/expert/submissions/${submissionId}/moderation`}
          className="underline underline-offset-2"
        >
          Moderation
        </Link>
      </p>
    </PageShell>
  );
}
